begin;
select plan(68);

insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',id,'authenticated','authenticated',id||'@phase2.invalid','{}','{}',now(),now()
from unnest(array['16000000-0000-4000-8000-000000000001'::uuid,'16000000-0000-4000-8000-000000000002','16000000-0000-4000-8000-000000000003','16000000-0000-4000-8000-000000000004'])id;
update public.profiles set full_name=case when id='16000000-0000-4000-8000-000000000001'then'Supervisor A'when id='16000000-0000-4000-8000-000000000002'then'Supervisor B'when id='16000000-0000-4000-8000-000000000003'then'Supervisor Other Org'else'Supervisor Other Branch'end,must_change_password=false where id::text like'16000000%';
insert into public.organizations(id,name,slug)values('26000000-0000-4000-8000-000000000001','Phase 2 A','phase-2-a'),('26000000-0000-4000-8000-000000000002','Phase 2 B','phase-2-b');
insert into public.branches(id,organization_id,name,code,timezone)values('36000000-0000-4000-8000-000000000001','26000000-0000-4000-8000-000000000001','Branch A','P2A','Asia/Riyadh'),('36000000-0000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002','Branch B','P2B','Asia/Riyadh'),('36000000-0000-4000-8000-000000000003','26000000-0000-4000-8000-000000000001','Branch A2','P2A2','Asia/Riyadh');
insert into public.branch_memberships(branch_id,user_id,role)values('36000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001','branch_manager'),('36000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000002','branch_manager'),('36000000-0000-4000-8000-000000000002','16000000-0000-4000-8000-000000000003','branch_manager'),('36000000-0000-4000-8000-000000000003','16000000-0000-4000-8000-000000000004','branch_manager');
insert into public.branch_supervisor_teams(id,organization_id,branch_id,supervisor_user_id)values('46000000-0000-4000-8000-000000000001','26000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001'),('46000000-0000-4000-8000-000000000002','26000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000002'),('46000000-0000-4000-8000-000000000003','26000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000002','16000000-0000-4000-8000-000000000003'),('46000000-0000-4000-8000-000000000004','26000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000003','16000000-0000-4000-8000-000000000004');

select is((select count(*)from public.checklist_submissions where checklist_type in('kitchen_opening','foh_opening','daily_audit')group by organization_id,branch_id,business_date,checklist_type having count(*)>1),null::bigint,'duplicate preflight has no branch checklist conflicts');
