select is((select count(*)from public.cold_storage_submissions group by organization_id,branch_id,business_date having count(*)>1),null::bigint,'duplicate preflight has no Cold conflicts');
select is((select count(*)from public.sales_tracking_reports group by organization_id,branch_id,business_date having count(*)>1),null::bigint,'duplicate preflight has no Sales conflicts');

select lives_ok($$select*from public.save_phase4a_draft('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001','kitchen_opening',0,(select jsonb_agg(jsonb_build_object('item_id',item_id,'answer','completed','remark','','evidence_id',null)order by ordinal)from public.checklist_definition_items where definition_id='kitchen_opening_v1'))$$,'A saves shared Kitchen Opening');
select is(public.get_phase4a_current_state('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001','kitchen_opening')->>'state','draft','B sees A Kitchen draft');
select throws_ok($$select*from public.save_phase4a_draft('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001','kitchen_opening',0,(select jsonb_agg(jsonb_build_object('item_id',item_id,'answer','completed','remark','','evidence_id',null)order by ordinal)from public.checklist_definition_items where definition_id='kitchen_opening_v1'))$$,'40001','opening draft changed','stale Opening writer conflicts');
