select lives_ok($$select*from public.save_phase4a_draft('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001','foh_opening',0,(select jsonb_agg(jsonb_build_object('item_id',item_id,'answer','completed','remark','','evidence_id',null)order by ordinal)from public.checklist_definition_items where definition_id='foh_opening_v1'))$$,'B saves shared FOH Opening');
