select is(public.get_phase4a_current_state('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001','foh_opening')->>'state','submitted','B sees shared submitted FOH Opening');

select lives_ok($$select public.save_oil_tracking_draft('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',0,'[{"fryer_id":"fryer-1","fryer_label_snapshot":"Fryer 1","fryer_short_label_snapshot":"F1","in_use_today":true,"oil_status":"new_oil","opening_temperature_c":175,"opening_status":"pass","opening_note":"","closing_tpm_percent":20,"closing_note":""}]')$$,'A saves shared Oil');
