select throws_ok($$select public.submit_oil_tracking_opening('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',(public.get_oil_tracking_current_state('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001')->>'revision')::bigint,'56000000-0000-4000-8000-000000000012',repeat('e',64),'[{"fryer_id":"fryer-1","fryer_label_snapshot":"Fryer 1","fryer_short_label_snapshot":"F1","in_use_today":true,"oil_status":"new_oil","opening_temperature_c":175,"opening_status":"pass","opening_note":"","closing_tpm_percent":20,"closing_note":""}]')$$,'23505','opening already submitted','submitted Oil opening cannot reopen');
