select lives_ok($$select public.save_cold_storage_draft('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',0,(select jsonb_build_array(jsonb_build_object('equipment_id',id,'equipment_name',name,'equipment_type',equipment_type,'active',true))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'),(select jsonb_build_array(jsonb_build_object('equipment_id',id,'slot','12:00','temperature_c',4,'status','pass','corrective_action',''))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'))$$,'A saves shared Cold draft');
