select lives_ok($$select public.submit_cold_storage_slot('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001',1,'12:00','56000000-0000-4000-8000-000000000003',repeat('c',64),(select jsonb_build_array(jsonb_build_object('equipment_id',id,'equipment_name',name,'equipment_type',equipment_type,'active',true))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'),(select jsonb_build_array(jsonb_build_object('equipment_id',id,'slot','12:00','temperature_c',4,'status','pass','corrective_action',''))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'))$$,'B submits A Cold slot');
select ok((public.get_cold_storage_current_state('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001')->'readings'->0->>'submitted_at')is not null,'A sees B Cold submission');
select is((select count(*)from public.cold_storage_submissions where branch_id='36000000-0000-4000-8000-000000000001'),1::bigint,'one Cold ledger exists');
select throws_ok($$select public.submit_cold_storage_slot('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',(public.get_cold_storage_current_state('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001')->>'revision')::bigint,'12:00','56000000-0000-4000-8000-000000000013',repeat('f',64),(select jsonb_build_array(jsonb_build_object('equipment_id',id,'equipment_name',name,'equipment_type',equipment_type,'active',true))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'),(select jsonb_build_array(jsonb_build_object('equipment_id',id,'slot','12:00','temperature_c',4,'status','pass','corrective_action',''))from public.branch_cold_storage_equipment where branch_id='36000000-0000-4000-8000-000000000001'))$$,'23505','cold storage slot already submitted','submitted Cold slot cannot reopen');
select throws_ok($$select public.get_cold_storage_current_state('16000000-0000-4000-8000-000000000004','36000000-0000-4000-8000-000000000001')$$,'42501','cold storage state denied','other branch cannot read Cold');
select throws_ok($$select public.get_cold_storage_current_state('16000000-0000-4000-8000-000000000003','36000000-0000-4000-8000-000000000001')$$,'42501','cold storage state denied','other organization cannot read Cold');

select lives_ok(format($$select public.save_sales_tracking_draft('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',0,'middle_shift','[{"entry_date":"%s","actual_cash":100,"actual_credit":50,"pos_cash":90,"pos_credit":60,"online_delivery":25,"remarks":"A"}]','[{"entry_date":"%s","remaining_cash":0}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'A saves shared Sales/Cash Middle Shift');
