select lives_ok(format($$select public.save_sales_tracking_draft('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001',1,'closing_shift','[{"entry_date":"%s","actual_cash":20,"actual_credit":30,"pos_cash":20,"pos_credit":30,"online_delivery":5,"remarks":"B"}]','[{"entry_date":"%s","remaining_cash":0}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'B saves Closing Shift');
