select throws_ok($$select public.get_sales_tracking_current_state('16000000-0000-4000-8000-000000000004','36000000-0000-4000-8000-000000000001')$$,'42501','sales tracking state denied','other branch cannot read Sales/Cash');
select throws_ok($$select public.get_sales_tracking_current_state('16000000-0000-4000-8000-000000000003','36000000-0000-4000-8000-000000000001')$$,'42501','sales tracking state denied','other organization cannot read Sales/Cash');

