select throws_ok($$select*from public.list_branch_supplier_receivings('16000000-0000-4000-8000-000000000003','36000000-0000-4000-8000-000000000001')$$,'42501','supplier receiving access denied','other organization cannot read Supplier Receiving');
select is((public.get_phase4a_supervisor_overview('16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001')->'checklists')::text,(public.get_phase4a_supervisor_overview('16000000-0000-4000-8000-000000000002','36000000-0000-4000-8000-000000000001')->'checklists')::text,'A and B receive identical branch Overview');
