select ok(not has_function_privilege('authenticated','public.list_phase2_branch_reports(uuid,uuid,int,int,text)','execute')and has_function_privilege('service_role','public.list_phase2_branch_reports(uuid,uuid,int,int,text)','execute'),'shared report RPC remains service-role only');
select is((select proconfig from pg_proc where oid='public.list_phase2_branch_reports(uuid,uuid,int,int,text)'::regprocedure),array['search_path=""'],'shared report RPC has empty search_path');

select * from finish();
rollback;
